import React, { useId } from 'react';

interface RadarIconProps {
  size?: number;
  className?: string;
}

/**
 * Pixel-accurate SVG representation of the unified rounded-square AMOLED Black
 * app, tray, window & .exe icon generated by build.rs and src/main.rs.
 */
export const RadarIcon: React.FC<RadarIconProps> = ({ size = 28, className = '' }) => {
  const uid = useId().replace(/:/g, '');
  const bgId = `radar-bg-${uid}`;
  const borderGradId = `radar-pw-${uid}`;
  const vGradId = `radar-v-${uid}`;

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 32 32"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-hidden="true"
    >
      <defs>
        <linearGradient id={bgId} x1="0" y1="0" x2="0" y2="32" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#000000" />
          <stop offset="100%" stopColor="#0A080E" />
        </linearGradient>
        <linearGradient id={borderGradId} x1="0" y1="32" x2="32" y2="0" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#FF4D94" />
          <stop offset="55%" stopColor="#FFA6D2" />
          <stop offset="100%" stopColor="#FFF5FA" />
        </linearGradient>
        <linearGradient id={vGradId} x1="16" y1="24" x2="16" y2="8" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#FFD2EA" />
          <stop offset="100%" stopColor="#FFF5FA" />
        </linearGradient>
      </defs>
      <rect x="1.5" y="1.5" width="29" height="29" rx="5.2" fill={`url(#${bgId})`} />
      <rect
        x="2"
        y="2"
        width="28"
        height="28"
        rx="4.8"
        stroke={`url(#${borderGradId})`}
        strokeWidth="2.1"
      />
      <path
        d="M8.6 8.6L16 23.6L23.4 8.6"
        stroke={`url(#${vGradId})`}
        strokeWidth="3.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <circle cx="16" cy="9.6" r="2.25" fill="#FF5CA8" />
    </svg>
  );
};
